  function applyColorTheme(key){const selected=themes[key]?key:'graphite';const t=themes[selected];const root=document.documentElement;root.dataset.colorTheme=selected;root.style.setProperty('--amt-theme-light',t.bg);root.style.setProperty('--amt-theme-dark',t.dark);root.style.setProperty('--amt-header-light',t.headerLight);root.style.setProperty('--amt-header-dark',t.headerDark);root.style.setProperty('--amt-header-border-light',t.borderLight);root.style.setProperty('--amt-header-border-dark',t.borderDark);root.style.setProperty('--amt-accent',t.accent);const meta=document.querySelector('meta[name="theme-color"]');if(meta)meta.setAttribute('content',document.documentElement.classList.contains('dark')?t.headerDark:t.headerLight);amtStorage.setItem(THEME_KEY,selected);['amtThemeMenuSelect','amtColorThemeSelect'].forEach(id=>{const el=document.getElementById(id);if(el&&el.value!==selected)el.value=selected;});}
