  function enhanceScaleForms(){
    const monthOptions=()=>{const out=[];const now=new Date();for(let i=-24;i<=36;i++){const d=new Date(now.getFullYear(),now.getMonth()+i,1),v=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');out.push({v,label:d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'})});}return out;};
    ['customScaleStartMonth','customScaleEndMonth','clearScaleMonth'].forEach(id=>{const el=document.getElementById(id);if(!el||el.tagName!=='SELECT')return;const old=el.value;el.innerHTML='<option value="" selected>'+(id==='clearScaleMonth'?'Selecionar mês':'Selecione o mês')+'</option>';monthOptions().forEach(o=>{const op=document.createElement('option');op.value=o.v;op.textContent=o.label;el.appendChild(op)});if(old)el.value=old;});
    const monthly=document.getElementById('monthlyScaleMonth');if(monthly){monthly.innerHTML='<option value="" selected>Selecione o mês</option>';monthOptions().forEach(o=>{const op=document.createElement('option');op.value=o.v;op.textContent=o.label;monthly.appendChild(op);});monthly.value='';}
    const monthDatePairs=[['monthlyScaleMonth','monthlyScaleBaseDate'],['customScaleStartMonth','customScaleBaseDate'],['customScaleStartMonth','customScaleBaseDate']];
    const updateDateBounds=(monthId,dateId)=>{const m=document.getElementById(monthId),d=document.getElementById(dateId);if(!m||!d)return;const key=m.value;if(key){const [y,mo]=key.split('-').map(Number);d.min=key+'-01';d.max=key+'-'+String(new Date(y,mo,0).getDate()).padStart(2,'0');}else{d.removeAttribute('min');d.removeAttribute('max');}};
    [['monthlyScaleMonth','monthlyScaleBaseDate'],['customScaleStartMonth','customScaleBaseDate']].forEach(([m,d])=>{const el=document.getElementById(m);if(el){el.addEventListener('change',()=>updateDateBounds(m,d));updateDateBounds(m,d);}});
    const start=document.getElementById('customScaleStartMonth'),end=document.getElementById('customScaleEndMonth'),date=document.getElementById('customScaleBaseDate');if(start&&end){start.addEventListener('change',()=>{if(start.value&&end.value<start.value){end.value=start.value;updateMonthDisplay(end);}if(date&&start.value){const [y,m]=start.value.split('-').map(Number);date.min=start.value+'-01';if(end.value){const [ey,em]=end.value.split('-').map(Number);date.max=ey+'-'+String(em).padStart(2,'0')+'-'+String(new Date(ey,em,0).getDate()).padStart(2,'0');}}});end.addEventListener('change',()=>{if(start.value&&end.value&&end.value<start.value){end.value=start.value;updateMonthDisplay(end);}if(date&&end.value){const [y,m]=end.value.split('-').map(Number);date.max=end.value+'-'+String(new Date(y,m,0).getDate()).padStart(2,'0');}});}
    const mt=document.getElementById('monthlyScaleType'),ct=document.getElementById('customScaleType');if(mt&&!mt.value)mt.value='';if(ct&&!ct.value)ct.value='';
  }
