  function closeMonthWheel(){const m=document.getElementById('amtMonthWheelModal');if(m){m.classList.add('hidden');m.classList.remove('flex');}monthWheelTarget=null;}
  function updateWheelVisuals(list){if(!list)return;const center=list.scrollTop+list.clientHeight/2;[...list.children].forEach(el=>{const distance=(el.offsetTop+el.offsetHeight/2-center)/el.offsetHeight;const abs=Math.abs(distance);const angle=Math.max(-68,Math.min(68,distance*23));const scale=Math.max(.68,1-abs*.115);const opacity=Math.max(.16,1-abs*.24);const blur=Math.min(3.2,abs*.72);el.classList.toggle('is-selected',abs<.48);el.style.opacity=String(opacity);el.style.filter='blur('+blur.toFixed(2)+'px)';el.style.transform='perspective(700px) rotateX('+angle.toFixed(1)+'deg) scale('+scale.toFixed(3)+')';});}
  function openMonthWheel(target){
    if(!target)return;monthWheelTarget=target;monthWheelItems=[];
    if(target.tagName==='SELECT')monthWheelItems=[...target.options].filter(o=>/^\d{4}-\d{2}$/.test(o.value)).map(o=>({value:o.value,label:o.textContent.trim()}));
    else {const now=new Date();for(let i=-60;i<=60;i++){const d=new Date(now.getFullYear(),now.getMonth()+i,1),value=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0');monthWheelItems.push({value,label:monthLabel(value)});}}
    if(!monthWheelItems.length){if(target.tagName==='SELECT')return;}
    const current=target.value;const now=new Date();const defaultValue=current&&/^\d{4}-\d{2}$/.test(current)?current:(now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0'));const parts=defaultValue.split('-').map(Number);monthWheelMonth=parts[1]||now.getMonth()+1;monthWheelYear=parts[0]||now.getFullYear();monthWheelSetValue();
    const years=monthWheelItems.length?Array.from(new Set(monthWheelItems.map(x=>Number(x.value.slice(0,4))))).sort((a,b)=>a-b):Array.from({length:11},(_,i)=>now.getFullYear()-5+i);
    const modal=ensureMonthWheel(),monthList=modal.querySelector('#amtMonthWheelMonths'),yearList=modal.querySelector('#amtMonthWheelYears');monthList.innerHTML='';yearList.innerHTML='';
    monthNamesPt.forEach((name,i)=>{const b=document.createElement('button');b.type='button';b.dataset.month=String(i+1);b.textContent=name;b.className='amt-wheel-item';b.onclick=()=>monthList.scrollTo({top:b.offsetTop-monthList.clientHeight/2+b.offsetHeight/2,behavior:'smooth'});monthList.appendChild(b);});
    years.forEach(year=>{const b=document.createElement('button');b.type='button';b.dataset.year=String(year);b.textContent=year;b.className='amt-wheel-item';b.style.textTransform='none';b.onclick=()=>yearList.scrollTo({top:b.offsetTop-yearList.clientHeight/2+b.offsetHeight/2,behavior:'smooth'});yearList.appendChild(b);});
    modal.classList.remove('hidden');modal.classList.add('flex');requestAnimationFrame(()=>{const mi=monthWheelMonth-1,yi=Math.max(0,years.indexOf(monthWheelYear));const me=monthList.children[mi],ye=yearList.children[yi];if(me)monthList.scrollTop=me.offsetTop-monthList.clientHeight/2+me.offsetHeight/2;if(ye)yearList.scrollTop=ye.offsetTop-yearList.clientHeight/2+ye.offsetHeight/2;updateWheelVisuals(monthList);updateWheelVisuals(yearList);});
  }
