    const monthValue=document.getElementById(monthId)?.value||'';if(!monthValue){alert(isMonthly?'Selecione primeiro o mês da escala.':'Selecione primeiro o mês inicial.');return;}
    const [yy,mm]=monthValue.split('-').map(Number);pickerMonth=new Date(yy,mm-1,1);pickerSelected=document.getElementById(dateId)?.value||'';activeDatePicker={which,dateId,monthId};
    let modal=document.getElementById('amtScaleDatePicker');if(!modal){modal=document.createElement('div');modal.id='amtScaleDatePicker';modal.className='fixed inset-0 z-[100] hidden items-center justify-center bg-black/60 p-3';modal.innerHTML='<div class="w-full max-w-sm rounded-2xl bg-white dark:bg-gray-900 p-4 shadow-2xl space-y-3"><div class="flex items-center justify-between"><button type="button" id="amtPickerPrev" class="rounded-lg px-3 py-2 bg-gray-100 dark:bg-gray-800">‹</button><strong id="amtPickerTitle" class="capitalize"></strong><button type="button" id="amtPickerNext" class="rounded-lg px-3 py-2 bg-gray-100 dark:bg-gray-800">›</button></div><div class="grid grid-cols-7 gap-1 text-center text-xs text-gray-500"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span><span>Dom</span></div><div id="amtPickerDays" class="grid grid-cols-7 gap-1"></div><div class="flex justify-between gap-2 pt-2"><button type="button" id="amtPickerBack" class="rounded-xl border border-gray-300 dark:border-gray-700 px-4 py-2 font-semibold">Voltar</button><button type="button" id="amtPickerOk" class="rounded-xl bg-amber-500 px-5 py-2 font-bold text-black">OK</button></div></div>';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal)closeScaleDatePicker();});modal.querySelector('#amtPickerPrev').onclick=()=>{pickerMonth.setMonth(pickerMonth.getMonth()-1);drawScaleDatePicker();};modal.querySelector('#amtPickerNext').onclick=()=>{pickerMonth.setMonth(pickerMonth.getMonth()+1);drawScaleDatePicker();};modal.querySelector('#amtPickerBack').onclick=closeScaleDatePicker;modal.querySelector('#amtPickerOk').onclick=()=>{if(!pickerSelected){alert('Selecione uma data.');return;}const hidden=document.getElementById(activeDatePicker.dateId);hidden.value=pickerSelected;const b=document.getElementById(activeDatePicker.dateId+'Display');const [y,m,d]=pickerSelected.split('-');b.textContent=d+'/'+m+'/'+y;b.classList.remove('text-gray-500');closeScaleDatePicker();};}
    modal.classList.remove('hidden');modal.classList.add('flex');drawScaleDatePicker();
