    if(typeof originalMonthly==='function')window.saveMonthlyScaleFromSettings=function(){const before=amtStorage.getItem('amt_month_scales'),month=document.getElementById('monthlyScaleMonth').value,date=document.getElementById('monthlyScaleBaseDate').value,scale=document.getElementById('monthlyScaleType').value;originalMonthly();let saved=false;try{saved=JSON.parse(amtStorage.getItem('amt_month_scales')||'[]').some(c=>c.startMonth===month&&c.endMonth===month&&c.baseDate===date&&c.scale===scale);}catch(_){}if(saved||amtStorage.getItem('amt_month_scales')!==before)resetScaleSelectors();};
