    const originalSave=window.saveDayModalData;if(typeof originalSave==='function')window.saveDayModalData=function(){const type=document.getElementById('modalExtraType')?.value,hours=document.getElementById('modalExtraHours')?.value;if(type==='hours'&&(!hours||Number(hours)<=0)){alert('Selecione a quantidade de horas extras.');return;}originalSave();setTimeout(()=>{if(typeof renderBankHours==='function')renderBankHours();},0);};
    ['clearSpecificScaleMonth','clearAllScaleConfigs'].forEach(name=>{const fn=window[name];if(typeof fn==='function')window[name]=function(){fn();const e=document.getElementById('clearScaleMonth');if(e)updateMonthDisplay(e);};});
    const oldToggle=window.toggleTheme;window.toggleTheme=function(){oldToggle();applyColorTheme(amtStorage.getItem(THEME_KEY)||'graphite');};
