    document.getElementById('monthlyScaleMonth')?.addEventListener('change',()=>{const e=document.getElementById('monthlyScaleBaseDate');if(e)e.value='';const b=document.getElementById('monthlyScaleBaseDateDisplay');if(b){b.textContent='Selecionar data';b.classList.add('text-gray-500');}});
